#!/usr/bin/env node

import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const catalogueDir = join(root, "scripts/v2-language/catalogue");
const args = process.argv.slice(2);
const outputIndex = args.indexOf("--cpp-output");
if (outputIndex < 0 || !args[outputIndex + 1])
  throw new Error("usage: generate-catalogue.mjs --cpp-output <path>");
const cppOutput = resolve(root, args[outputIndex + 1]);
const tsOutputIndex = args.indexOf("--ts-output");
const tsOutput = tsOutputIndex >= 0 && args[tsOutputIndex + 1]
  ? resolve(root, args[tsOutputIndex + 1]) : null;

const escapeCpp = (value) => String(value).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
const quote = (value) => `"${escapeCpp(value)}"`;
const packed = (values) => quote(values.join("\u001f"));

const files = readdirSync(catalogueDir)
  .filter((file) => file.endsWith(".mjs"))
  .sort();
if (files.length === 0) throw new Error("V2 catalogue has no syntax-family definitions");

const entries = [];
for (const file of files) {
  const module = await import(pathToFileURL(join(catalogueDir, file)).href);
  if (!Array.isArray(module.default)) throw new Error(`${file} must default-export an array`);
  for (const entry of module.default) entries.push({ ...entry, source: `scripts/v2-language/catalogue/${file}` });
}

const ids = new Set();
const completionOwners = new Map();
for (const entry of entries) {
  for (const field of ["id", "name", "family"]) {
    if (typeof entry[field] !== "string" || entry[field].length === 0)
      throw new Error(`${entry.source}: ${field} is required for every entry`);
  }
  if (ids.has(entry.id)) throw new Error(`duplicate V2 catalogue identity: ${entry.id}`);
  ids.add(entry.id);
  if (!Array.isArray(entry.syntax) || entry.syntax.length === 0)
    throw new Error(`${entry.id}: canonical syntax is required`);
  if (!Array.isArray(entry.contexts) || entry.contexts.length === 0)
    throw new Error(`${entry.id}: legal contexts are required`);
  if (typeof entry.example !== "string" || entry.example.trim().length === 0)
    throw new Error(`${entry.id}: one canonical checked example is required`);
  if (!Array.isArray(entry.arguments))
    throw new Error(`${entry.id}: argument metadata must be an array (use [] when it has no call arguments)`);
  for (const argument of entry.arguments) {
    if (typeof argument?.name !== "string" || !argument.name
        || typeof argument?.type !== "string" || !argument.type)
      throw new Error(`${entry.id}: every argument needs a name and type`);
  }
  if (!entry.binding?.parser || !entry.binding?.compiler)
    throw new Error(`${entry.id}: parser and compiler binding names are required`);
  if (entry.completion) {
    if (!entry.completion.label || !entry.completion.insert || !entry.completion.summary)
      throw new Error(`${entry.id}: completion requires label, insertion and summary`);
    const owners = completionOwners.get(entry.completion.label) ?? [];
    if (owners.some((owner) => owner.contexts.some((context) => entry.contexts.includes(context))))
      throw new Error(`duplicate V2 completion label in the same context: ${entry.completion.label}`);
    owners.push(entry);
    completionOwners.set(entry.completion.label, owners);
  }
}

const rows = entries.sort((a, b) => a.id.localeCompare(b.id)).map((entry) =>
  `V2_CATALOGUE_ENTRY(${quote(entry.id)}, ${quote(entry.name)}, ${quote(entry.family)}, ${packed(entry.syntax)}, ${packed(entry.contexts)}, ${quote(entry.support ?? "implemented")}, ${quote(entry.binding.parser)}, ${quote(entry.binding.compiler)}, ${entry.completion ? quote(entry.completion.label) : "nullptr"}, ${entry.completion ? quote(entry.completion.insert) : "nullptr"}, ${entry.completion ? quote(entry.completion.summary) : "nullptr"}, ${entry.completion ? quote(entry.completion.kind) : "nullptr"})`
);

mkdirSync(dirname(cppOutput), { recursive: true });
writeFileSync(cppOutput, `// Generated by scripts/v2-language/generate-catalogue.mjs. Do not edit.\n${rows.join("\n")}\n`);
if (tsOutput) {
  mkdirSync(dirname(tsOutput), { recursive: true });
  const editorEntries = entries.sort((a, b) => a.id.localeCompare(b.id)).map((entry) => [
    entry.name,
    entry.family,
    entry.completion?.label ?? null,
    entry.completion?.insert ?? null,
    entry.completion?.summary ?? null,
    entry.completion?.kind ?? null,
  ]);
  writeFileSync(tsOutput, `// Generated by scripts/v2-language/generate-catalogue.mjs. Do not edit.\n// [name, family, completion label, insertion, summary, kind]\nexport const scriptV2Catalogue = ${JSON.stringify(editorEntries)} as const;\n`);
}
console.log(`V2 catalogue: ${entries.length} constructs from ${files.length} syntax families`);
